... | yes _ = Low
... | no _ with conf ≤? 70.0
... | yes _ = Medium
... | no _ with conf ≤? 90.0
... | yes _ = High
... | no _ = VeryHigh

-- Theorem: Valid protein structures have bounded LDDT scores
lddt-bounded : ∀ (predicted reference : ProteinStructure) →
  ValidProteinStructure predicted → ValidProteinStructure reference →
  let score = LDDT predicted reference
  in 0 / 1 ≤ᵺ score ∧ score ≤ᵺ 1 / 1
